static class UiLanguage {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static string locale="zh-CN";static Dictionary<string,string> reverse=new Dictionary<string,string>();static long checkedAt;static Dictionary<string,object> words=new Dictionary<string,object>();
 public static string Locale {get{Refresh();return locale;}}
 static void Refresh(){long now=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();if(now-checkedAt<300)return;checkedAt=now;try{string app=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../../mhub-community-assistant"));string file=Path.Combine(app,"state/ui-preferences.json");string next="zh-CN";if(File.Exists(file)){var pref=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file,Encoding.UTF8));next=Convert.ToString(pref["locale"]);}if(next!=locale||words.Count==0){if(Array.IndexOf(new string[]{"zh-CN","ru","en","fr","it"},next)<0)next="zh-CN";words=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(app,"panel/i18n/"+next+".json"),Encoding.UTF8));locale=next;if(reverse.Count==0){foreach(string language in new string[]{"en","ru","fr","it"}){var table=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(app,"panel/i18n/"+language+".json"),Encoding.UTF8));foreach(var pair in table){if(pair.Value!=null)reverse[Convert.ToString(pair.Value)]=pair.Key;}}}}}catch{}}
 public static string Get(string text){Refresh();return System.Text.RegularExpressions.Regex.Replace(text,@"[^\r\n]+",m=>{string core=m.Value.Trim(),original;object value;if(!words.ContainsKey(core)&&reverse.TryGetValue(core,out original))core=original;if(words.TryGetValue(core,out value)&&value!=null)return m.Value.Substring(0,m.Value.Length-m.Value.TrimStart().Length)+Convert.ToString(value)+m.Value.Substring(m.Value.TrimEnd().Length);return m.Value;});}
}

static class CallStyle {
 public static readonly Color Background=ColorTranslator.FromHtml("#F5F5F7"),Ink=ColorTranslator.FromHtml("#1D1D1F"),Muted=ColorTranslator.FromHtml("#86868B"),Blue=ColorTranslator.FromHtml("#007AFF"),Green=ColorTranslator.FromHtml("#34C759"),Red=ColorTranslator.FromHtml("#FF3B30"),Line=ColorTranslator.FromHtml("#E5E5EA"),Notice=Color.FromArgb(238,239,242);
 public static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 public static Font Font(float px,FontStyle style=FontStyle.Regular){return new Font("Microsoft YaHei UI",px,style,GraphicsUnit.Pixel);}
 public static void Icon(Graphics g,string kind,RectangleF box,Color color){var save=g.Save();g.TranslateTransform(box.X,box.Y);g.ScaleTransform(box.Width/24,box.Height/24);g.SmoothingMode=SmoothingMode.AntiAlias;
  using(var pen=new Pen(color,1.8f)){pen.StartCap=pen.EndCap=LineCap.Round;pen.LineJoin=LineJoin.Round;
   if(kind=="accept"){using(var p=new GraphicsPath()){p.AddBezier(6,3,3,3,2,5,3,9);p.AddBezier(3,9,5,16,11,21,17,21);p.AddBezier(17,21,20,21,22,19,21,17);p.AddLine(21,17,17,14);p.AddLine(17,14,14,17);p.AddBezier(14,17,10,15,7,12,7,9);p.AddLine(7,9,10,7);p.AddLine(10,7,8,3);p.CloseFigure();using(var b=new SolidBrush(color))g.FillPath(b,p);}}
   else if(kind=="end"){using(var p=new GraphicsPath()){p.AddBezier(3,15,2,7,22,7,21,15);pen.Width=4.2f;g.DrawPath(pen,p);}}
   else if(kind=="mic"||kind=="muted"){g.DrawArc(pen,9,3,6,12,180,180);g.DrawArc(pen,9,3,6,12,0,180);g.DrawArc(pen,6,7,12,12,0,180);g.DrawLine(pen,12,19,12,22);g.DrawLine(pen,8,22,16,22);if(kind=="muted")g.DrawLine(pen,3,3,21,21);}
   else if(kind=="headphones"){g.DrawArc(pen,4,3,16,16,180,180);g.DrawLine(pen,4,11,4,18);g.DrawLine(pen,20,11,20,18);g.DrawRectangle(pen,3,13,4,7);g.DrawRectangle(pen,17,13,4,7);}
   else if(kind=="keyboard"){g.DrawRectangle(pen,2,5,20,14);for(int r=0;r<2;r++)for(int c=0;c<5;c++)g.DrawLine(pen,5+c*3.5f,9+r*3,5.5f+c*3.5f,9+r*3);g.DrawLine(pen,8,16,16,16);}
  }g.Restore(save);
 }
}
