   else{phase.Text=p=="ended"?UiLanguage.Get("通话已结束"):Str(state,"direction")=="outgoing"?UiLanguage.Get("正在呼叫"):UiLanguage.Get("正在接通");subtitle.Text=p=="ended"?UiLanguage.Get("下次再聊，随时找我"):UiLanguage.Get("等待接通，语音就绪后开始计时");shortcut.Text=Str(controls,"hotkey","Ctrl+Alt+F8")+UiLanguage.Get(" 可挂断");privacyMain.Text=p=="ended"?UiLanguage.Get("本次通话已结束"):UiLanguage.Get("正在准备开场语音");privacySub.Text=p=="ended"?UiLanguage.Get("已停止本次通话收音"):UiLanguage.Get("语音就绪后自动接通，无需一直按住按键");}
   if(direct&&(p=="dialing"||p=="connecting"))privacyMain.Text=UiLanguage.Get("正在接通 Live2D 桌宠");
   phase.DotColor=p=="ended"?CallStyle.Muted:CallStyle.Green;string error=Str(state,"error");if(error!=""){privacyMain.Text=UiLanguage.Get("通话遇到问题");privacySub.Text=UiLanguage.Get("点开通话详情，查看完整错误信息");if(error!=lastExpandedError&&!detailsOpen){detailsOpen=true;changed=true;}}lastExpandedError=error;
   string body=(error!=""?UiLanguage.Get("错误：")+error+"\r\n\r\n":"")+UiLanguage.Get("你：")+Str(state,"input")+UiLanguage.Get("\r\n\r\n大肥鱼：")+Str(state,"reply")+UiLanguage.Get("\r\n\r\n播放设备：")+outputName+UiLanguage.Get("\r\n麦克风：")+inputName+(deviceError!=""?UiLanguage.Get("\r\n设备信息：")+deviceError:"")+UiLanguage.Get(direct?"\r\n\r\n连续听话：Live2D 桌宠":"\r\n\r\n连续听话：鱼搭子 · Yuuyuko-uu");if(transcript.Text!=body){transcript.Text=body;transcript.SelectionStart=error!=""?0:transcript.TextLength;transcript.ScrollToCaret();}shortcut.AccessibleName=shortcut.Text;tooltip.SetToolTip(shortcut,p=="incoming"&&Bool(keyboard,"ready")?UiLanguage.Get("将绿色 ")+key+UiLanguage.Get(" 键按到底接听，原有按下与释放逻辑保持不变。"):shortcut.Text);if(changed)ApplyLayout();if(!direct)QueryDevices();
   if(Now-lastPublish>500){lastPublish=Now;File.WriteAllText(Path.Combine(root,"panel-status.json"),json.Serialize(new Dictionary<string,object>{{"pid",Process.GetCurrentProcess().Id},{"parent",parent},{"callId",callId},{"visible",Visible},{"handle",Handle.ToInt64()},{"at",Now}}),new UTF8Encoding(false));}
  }catch(Exception e){try{File.AppendAllText(Path.Combine(root,"panel.error.log"),e.Message+"\n");}catch{}}
 }
 static void EnableDpi(){try{if(SetProcessDpiAwarenessContext(new IntPtr(-4)))return;}catch{}try{if(SetProcessDpiAwareness(2)==0)return;}catch{}try{SetProcessDPIAware();}catch{}}
 void SaveAudit(string file){
  File.AppendAllText(file+".trace.txt","capture started\n");var checks=new List<object>();var problems=new List<string>();var visible=new List<Control>();
  using(var g=CreateGraphics())foreach(Control c in Controls)if(c.Visible){visible.Add(c);bool outside=c.Left<0||c.Top<0||c.Right>ClientSize.Width||c.Bottom>ClientSize.Height;if(outside)problems.Add("Outside: "+c.AccessibleName+" "+c.Text);bool clipped=c is CrispLabel&&g.MeasureString(c.Text,c.Font).Height>c.Height+2; if(clipped)problems.Add("Text height: "+c.Text);checks.Add(new{type=c.GetType().Name,text=c.Text,name=c.AccessibleName,x=c.Left,y=c.Top,width=c.Width,height=c.Height,font=c.Font.Size,outside=outside,textHeightClipped=clipped});}
  for(int i=0;i<visible.Count;i++)for(int j=i+1;j<visible.Count;j++)if(visible[i].Bounds.IntersectsWith(visible[j].Bounds))problems.Add("Overlap: "+visible[i].GetType().Name+" / "+visible[j].GetType().Name);
  using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(file,System.Drawing.Imaging.ImageFormat.Png);}
  File.WriteAllText(file+".json",json.Serialize(new{phase=phaseValue,systemDpi=dpi,contentScale=scale,width=Width,height=Height,output=outputName,input=inputName,controls=checks,problems=problems}),new UTF8Encoding(false));
 }
 [STAThread]public static void Main(string[] args){string appRoot=AppDomain.CurrentDomain.BaseDirectory;EnableDpi();try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);int parent=int.Parse(args[0]);string dataRoot=appRoot,audit=null;float? scale=null;for(int i=1;i<args.Length;i++){if(args[i]=="--ui-test-dir")dataRoot=Path.GetFullPath(args[++i]);else if(args[i]=="--ui-test-scale")scale=float.Parse(args[++i],System.Globalization.CultureInfo.InvariantCulture);else if(args[i]=="--ui-audit")audit=Path.GetFullPath(args[++i]);}if(scale.HasValue&&(scale<1||scale>2))throw new Exception("UI test scale outside supported range");var form=new FishCall(dataRoot,parent,scale);if(audit!=null){if(dataRoot==appRoot)throw new Exception("Audit requires an isolated UI fixture");form.auditMode=true;form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-10000,-10000);File.WriteAllText(audit+".trace.txt","audit scheduled\n");var captureTimer=new System.Windows.Forms.Timer{Interval=1200};form.Shown+=(s,e)=>captureTimer.Start();captureTimer.Tick+=(s,e)=>{captureTimer.Stop();try{form.SaveAudit(audit);}catch(Exception error){File.AppendAllText(audit+".trace.txt",error.ToString());}finally{form.autoClose=true;form.Close();captureTimer.Dispose();}};}Application.Run(form);}catch(Exception e){File.AppendAllText(Path.Combine(appRoot,"panel.error.log"),e+"\n");}}
}
